INSERT INTO modulos (id, ordem, dados, status) VALUES ('vendas', 1, '{"nome":"Vendas","subtitulo":"Comercial","objetivo":"Gerenciar o processo comercial, da criação do pedido ao faturamento. Integrado ao CEM, importa orçamentos sem redigitação.","papel":"Inicia o fluxo operacional. Alimenta Faturamento, Fiscal, Financeiro, Produção e Expedição.","quando":"Após configuração dos cadastros básicos e, preferencialmente, com integração CEM configurada.","prerequisito":"","fluxoDesc":"Da importação do orçamento à liberação para os módulos operacionais.","treinamento":"Priorize exemplos reais da empresa. O fluxo pode ser adaptado (ex: usar status \"Encerrado\" e gerar títulos antes do \"Faturado\"). O importante é que os usuários compreendam a lógica do processo.","icone":"vendas","cor":"#1976d2","tags":["vendas"],"fluxo":[{"id":"vendas-fluxo-1","texto":"Projeto no CEM","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-fluxo-2","texto":"Integração do orçamento","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-fluxo-3","texto":"Pedido de venda","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-fluxo-4","texto":"Faturamento","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-fluxo-5","texto":"Geração da NF","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-fluxo-6","texto":"Contas a Receber","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-fluxo-7","texto":"Liberação para Serviços, Produção e Expedição","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"vendas-boaspraticas-1","texto":"Validar dados importados antes da aprovação","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-boaspraticas-2","texto":"Explicar a importância dos status do pedido","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-boaspraticas-3","texto":"Demonstrar faturamento parcial quando aplicável","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-boaspraticas-4","texto":"Relacionar sempre aos demais módulos","status":null,"statusEm":null,"statusPor":""}],"checklist":[{"id":"vendas-checklist-1","texto":"Importar orçamento do CEM (quando aplicável)","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-checklist-2","texto":"Cadastrar e aprovar pedido de venda","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-checklist-3","texto":"Realizar faturamento","status":null,"statusEm":null,"statusPor":""},{"id":"vendas-checklist-4","texto":"Compreender integração com Faturamento, Financeiro, Serviços, Produção e Expedição","status":null,"statusEm":null,"statusPor":""}]}'::jsonb, NULL)
