INSERT INTO modulos (id, ordem, dados, status) VALUES ('faturamento', 2, '{"nome":"Faturamento","subtitulo":"Fiscal","objetivo":"Emitir documentos fiscais (NF-e/NFS-e), transmitir aos órgãos fiscais e integrar com Financeiro, Estoque e Expedição.","papel":"Conecta a área comercial às etapas fiscais e operacionais.","quando":"Após o módulo de Vendas e configuração das regras fiscais (CFOP, NCM, impostos, certificado digital).","prerequisito":"","fluxoDesc":"Da geração da nota fiscal à liberação para expedição.","treinamento":"Use um pedido previamente cadastrado. Demonstre da geração da nota até a autorização. Explique carta de correção, cancelamento, inutilização e contingência.","icone":"faturamento","cor":"#f57f17","tags":["fiscal"],"fluxo":[{"id":"faturamento-fluxo-1","texto":"Pedido de Venda","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-fluxo-2","texto":"Geração da NF-e/NFS-e","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-fluxo-3","texto":"Cálculo dos impostos","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-fluxo-4","texto":"Transmissão à SEFAZ/Prefeitura","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-fluxo-5","texto":"Autorização","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-fluxo-6","texto":"Contas a Receber","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-fluxo-7","texto":"Baixa de Estoque","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-fluxo-8","texto":"Liberação para Expedição","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"faturamento-boaspraticas-1","texto":"Validar configurações fiscais antes dos testes","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-boaspraticas-2","texto":"Conferir certificado digital e validade","status":null,"statusEm":null,"statusPor":""},{"id":"faturamento-boaspraticas-3","texto":"Orientar sobre impactos da autorização e cancelamento","status":null,"statusEm":nul