INSERT INTO modulos (id, ordem, dados, status) VALUES ('financeiro', 3, '{"nome":"Financeiro","subtitulo":"Gestão","objetivo":"Gerenciar movimentações financeiras — contas a receber, contas a pagar, cobranças, pagamentos, conciliação bancária e fluxo de caixa.","papel":"Recebe informações de Vendas, Faturamento, Compras e Recebimento. Elimina lançamentos manuais.","quando":"Após Vendas, Faturamento e configurações financeiras (plano de contas, contas bancárias, meios e condições de pagamento).","prerequisito":"","fluxoDesc":"Da geração automática de títulos à análise de resultado.","treinamento":"Use situações reais. Demonstre da geração automática à baixa, conciliação e demonstrativos. Relacione lançamentos aos processos que os originaram.","icone":"financeiro","cor":"#2e7d32","tags":["gestao"],"fluxo":[{"id":"financeiro-fluxo-1","texto":"Pedido de Venda/NF","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-fluxo-2","texto":"Geração automática dos títulos","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-fluxo-3","texto":"Cobrança (boleto/PIX)","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-fluxo-4","texto":"Recebimento ou pagamento","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-fluxo-5","texto":"Conciliação bancária","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-fluxo-6","texto":"Fluxo de Caixa","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-fluxo-7","texto":"DRE e Resultado por Obra","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"financeiro-boaspraticas-1","texto":"Configurar contas bancárias, plano de contas e meios de pagamento antes de operar","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-boaspraticas-2","texto":"Incentivar geração automática de títulos","status":null,"statusEm":null,"statusPor":""},{"id":"financeiro-boaspraticas-3","texto":"Demonstrar importância da conciliação e fluxo de caixa","status":null,"statusEm":n