INSERT INTO modulos (id, ordem, dados, status) VALUES ('estoque', 8, '{"nome":"Estoque","subtitulo":"Operação","objetivo":"Controlar movimentação de materiais. No Faktory Flow, o estoque é controlado por características (cor, largura, altura, comprimento), ideal para esquadrias.","papel":"Módulo central. Integra-se a Compras, Recebimento, Produção, Vendas e Faturamento. Saldos atualizados automaticamente.","quando":"Após configuração dos cadastros de produtos e antes de Compras, Produção e Recebimento.","prerequisito":"","fluxoDesc":"Da entrada de mercadorias à reposição automática.","treinamento":"Apresente saldo por características, movimentações, reservas, transferências, inventário e reposição automática. Demonstre consulta de saldos e integração com a operação.","icone":"estoque","cor":"#455a64","tags":["operacao"],"fluxo":[{"id":"estoque-fluxo-1","texto":"Entrada de Mercadorias","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-fluxo-2","texto":"Controle de Saldo","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-fluxo-3","texto":"Reserva de Materiais","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-fluxo-4","texto":"Movimentações","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-fluxo-5","texto":"Consumo pela Produção ou Faturamento","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-fluxo-6","texto":"Reposição Automática","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"estoque-boaspraticas-1","texto":"Manter cadastros de produtos e características atualizados","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-boaspraticas-2","texto":"Evitar movimentações manuais quando houver processos integrados","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-boaspraticas-3","texto":"Realizar inventários periódicos","status":null,"statusEm":null,"statusPor":""},{"id":"estoque-boaspraticas-4","texto":"Acompanhar materiais abaixo do estoque mínimo","status":null,"statusEm":