INSERT INTO modulos (id, ordem, dados, status) VALUES ('servicos', 10, '{"nome":"Serviços e Instalação","subtitulo":"Operação","objetivo":"Controlar atividades fora da fábrica — medição em obra, instalação, vistoria e assistência técnica.","papel":"Conecta processos comercial, produtivo e operacional. Acompanha a execução em campo.","quando":"Após Vendas, Produção e Expedição.","prerequisito":"","fluxoDesc":"Da venda à assistência técnica pós-instalação.","treinamento":"Apresente medição em campo (medidas, fotos, observações, assinaturas). Demonstre acompanhamento da instalação (agenda, equipe, checklist, registro fotográfico, aceite). Apresente vistoria e assistência técnica (histórico, atendimentos, evidências).","icone":"servicos","cor":"#ad1457","tags":["operacao"],"fluxo":[{"id":"servicos-fluxo-1","texto":"Venda","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-fluxo-2","texto":"Medição em Obra","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-fluxo-3","texto":"Aprovação das Medidas","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-fluxo-4","texto":"Produção","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-fluxo-5","texto":"Agendamento da Instalação","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-fluxo-6","texto":"Execução do Serviço","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-fluxo-7","texto":"Vistoria","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-fluxo-8","texto":"Assistência Técnica","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"servicos-boaspraticas-1","texto":"Realizar medição antes de liberar produção","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-boaspraticas-2","texto":"Registrar fotos e observações em todas as etapas","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-boaspraticas-3","texto":"Usar checklists para padronizar execução","status":null,"statusEm":null,"statusPor":""},{"id":"servicos-boasp