INSERT INTO modulos (id, ordem, dados, status) VALUES ('projetos', 11, '{"nome":"Projetos e Obras","subtitulo":"Gestão","objetivo":"Centralizar informações das obras — do planejamento à conclusão. Transforma cada obra em centro de controle e resultado.","papel":"Conecta todos os processos da obra. Evita informações espalhadas em planilhas.","quando":"Após Vendas, Compras, Produção, Estoque e Financeiro.","prerequisito":"","fluxoDesc":"Do cadastro da obra à análise de resultado.","treinamento":"Apresente cadastro da obra (cliente, responsável, datas, endereço, orçamento, etapas). Demonstre planejamento de materiais (previsto, comprado, recebido, consumido). Apresente painel operacional e financeiro (orçamento vs. realizado, margem, diário de obra).","icone":"projetos","cor":"#00695c","tags":["gestao"],"fluxo":[{"id":"projetos-fluxo-1","texto":"Cadastro da Obra","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-fluxo-2","texto":"Planejamento de Materiais","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-fluxo-3","texto":"Compras e Produção","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-fluxo-4","texto":"Execução da Obra","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-fluxo-5","texto":"Acompanhamento Operacional","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-fluxo-6","texto":"Controle Financeiro","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-fluxo-7","texto":"Encerramento e Análise de Resultado","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"projetos-boaspraticas-1","texto":"Criar obras com informações completas","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-boaspraticas-2","texto":"Usar planejamento de materiais antes de executar","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-boaspraticas-3","texto":"Acompanhar custos vs. orçamento","status":null,"statusEm":null,"statusPor":""},{"id":"projetos-boaspraticas-4","texto":"Registrar