INSERT INTO modulos (id, ordem, dados, status) VALUES ('fiscal', 12, '{"nome":"Fiscal","subtitulo":"Fiscal","objetivo":"Centralizar e automatizar cálculos tributários. Reduzir erros e divergências entre pedido e nota fiscal.","papel":"Motor tributário do Faktory Flow. Usado por todos os processos que envolvem impostos.","quando":"No início da implantação dos processos fiscais, antes de Vendas, Compras e Faturamento.","prerequisito":"Informações fiscais alinhadas com o cliente e contador (regime tributário, regras, NCM, CFOP, CST/CSOSN).","fluxoDesc":"Da configuração fiscal à conferência dos impostos.","treinamento":"Apresente cadastros fiscais: NCM, CFOP, CST/CSOSN, CEST, perfis fiscais, textos fiscais, regras de tributação. Demonstre aplicação dos impostos no pedido de venda. Apresente faturamento e envio à SEFAZ. Finalize com compras e recebimentos (impostos de entrada).","icone":"fiscal","cor":"#c62828","tags":["fiscal"],"fluxo":[{"id":"fiscal-fluxo-1","texto":"Configuração Fiscal","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-fluxo-2","texto":"Venda","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-fluxo-3","texto":"Faturamento","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-fluxo-4","texto":"Compra","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-fluxo-5","texto":"Recebimento","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-fluxo-6","texto":"Conferência dos Impostos","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"fiscal-boaspraticas-1","texto":"Validar configurações fiscais com o contador","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-boaspraticas-2","texto":"Manter NCMs, CFOPs e situações tributárias atualizados","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-boaspraticas-3","texto":"Evitar alterações sem avaliar impacto","status":null,"statusEm":null,"statusPor":""},{"id":"fiscal-boaspraticas-4","texto":"Conferir impostos antes de emitir notas","sta