INSERT INTO modulos (id, ordem, dados, status) VALUES ('tarefas', 14, '{"nome":"Tarefas","subtitulo":"Gestão","objetivo":"Organizar e acompanhar atividades das equipes. Controlar responsabilidades, prazos e andamento através de quadros visuais.","papel":"Organiza fluxo de trabalho com quadros, colunas e cartões. Cada tarefa pode ter responsável, prazo, prioridade, checklist, comentários, anexos e histórico.","quando":"Após os processos que utilizarão o gerenciamento de atividades (Projetos e Obras, CRM, etc.).","prerequisito":"","fluxoDesc":"Da criação da tarefa à conclusão.","treinamento":"Apresente criação de quadros e colunas. Demonstre criação de cartões (responsáveis, prazos, prioridades, checklists, anexos, comentários). Apresente recursos de acompanhamento (painel, filtros, indicadores de atraso). Finalize com modelos e automações.","icone":"tarefas","cor":"#00897b","tags":["gestao"],"fluxo":[{"id":"tarefas-fluxo-1","texto":"Criação da Tarefa","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-fluxo-2","texto":"Definição do Responsável e Prazo","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-fluxo-3","texto":"Execução da Atividade","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-fluxo-4","texto":"Acompanhamento","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-fluxo-5","texto":"Conclusão","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"tarefas-boaspraticas-1","texto":"Criar quadros seguindo processos reais","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-boaspraticas-2","texto":"Definir responsável para cada tarefa","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-boaspraticas-3","texto":"Usar prazos e prioridades","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-boaspraticas-4","texto":"Registrar informações dentro da tarefa","status":null,"statusEm":null,"statusPor":""},{"id":"tarefas-boaspraticas-5","texto":"Criar modelos para atividades repetitivas",