INSERT INTO modulos (id, ordem, dados, status) VALUES ('alumina', 15, '{"nome":"Alumina (IA)","subtitulo":"Inovação","objetivo":"Assistente inteligente dentro do Faktory Flow. Consultar informações, realizar análises e executar ações por comandos em linguagem natural (texto ou voz).","papel":"Camada inteligente sobre os módulos. Respeita permissões do usuário. Ações que alteram dados só executam após confirmação.","quando":"Após os principais módulos operacionais, com dados suficientes para consultas.","prerequisito":"","fluxoDesc":"Da pergunta do usuário à execução registrada.","treinamento":"Apresente perguntas por texto ou voz. Exemplos: \"Quais pedidos estão pendentes de faturamento?\", \"Qual foi o faturamento deste mês?\", \"Quais títulos estão vencidos?\", \"Como está a margem de uma obra?\". Demonstre interpretação, respostas, gráficos e sugestões. Apresente execução de ações assistidas (sempre com confirmação). Finalize com recursos de segurança (permissões, registros, restrições).","icone":"alumina","cor":"#6a1b9a","tags":["gestao"],"fluxo":[{"id":"alumina-fluxo-1","texto":"Pergunta do Usuário","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-fluxo-2","texto":"Consulta das Informações","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-fluxo-3","texto":"Análise dos Dados","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-fluxo-4","texto":"Sugestão de Ação","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-fluxo-5","texto":"Confirmação","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-fluxo-6","texto":"Execução Registrada","status":null,"statusEm":null,"statusPor":""}],"boasPraticas":[{"id":"alumina-boaspraticas-1","texto":"Usar perguntas claras e relacionadas ao processo","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-boaspraticas-2","texto":"Confirmar informações antes de executar ações","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-boaspraticas-3","texto":"Usar a IA como apoio à decisão","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-boaspraticas-4","texto":"Garantir permissões corretas","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-boaspraticas-5","texto":"Manter dados atualizados","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-boaspraticas-6","texto":"Usar a base de conhecimento da empresa","status":null,"statusEm":null,"statusPor":""}],"checklist":[{"id":"alumina-checklist-1","texto":"Realizar perguntas por texto ou voz","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-checklist-2","texto":"Consultar informações dos módulos","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-checklist-3","texto":"Interpretar respostas e gráficos","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-checklist-4","texto":"Solicitar sugestões de ações","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-checklist-5","texto":"Compreender processo de confirmação","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-checklist-6","texto":"Entender permissões e segurança","status":null,"statusEm":null,"statusPor":""},{"id":"alumina-checklist-7","texto":"Compreender integração com Vendas, Financeiro, Compras, Produção, Estoque, Projetos, CRM e demais módulos","status":null,"statusEm":null,"statusPor":""}]}'::jsonb, 'rever')
