INSERT INTO modulos_historico (modulo_id, acao, detalhe)
SELECT m.id, 'importado', CASE WHEN m.status = 'rever' THEN 'Importado do guia original (marcado para rever)' ELSE 'Importado do guia original' END
FROM modulos m
WHERE NOT EXISTS (SELECT 1 FROM modulos_historico h WHERE h.modulo_id = m.id);
